'use strict';
const form=document.querySelector('#registration'),status=document.querySelector('#status'),button=document.querySelector('#submit');
let requestId=crypto.randomUUID();
form.addEventListener('input',()=>{requestId=crypto.randomUUID()});
fetch('courses.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(courses=>{const course=document.querySelector('#course');course.innerHTML='';for(const c of courses){const option=document.createElement('option');option.value=c.slug;option.textContent=c.title;course.append(option)}const selected=new URLSearchParams(location.search).get('course');if(courses.some(c=>c.slug===selected))course.value=selected;updateCourseDisplay(courses)}).catch(()=>{status.textContent='Courses could not load. Please refresh.';button.disabled=true});
const result=new URLSearchParams(location.search).get('result');
if(result==='received')status.textContent='Your checkout submission was received. Registration and payment status will be confirmed after Stripe processes the payment. Monthly authorization does not itself confirm a successful charge.';
if(result==='cancelled')status.textContent='Checkout was cancelled. You can return to complete your registration.';
form.addEventListener('submit',async e=>{e.preventDefault();const api=(window.REGISTRATION_API_URL||'').replace(/\/$/,'');if(!(api.startsWith('https://') || (location.hostname==='127.0.0.1' && api==='http://127.0.0.1:8000'))){status.textContent='Online registration is not open yet. Please check back once checkout setup is complete.';return}button.disabled=true;status.textContent=window.REGISTRATION_MODE==='payment'?'Opening secure checkout…':'Submitting registration…';const data=Object.fromEntries(new FormData(form));data.consent=form.elements.consent.checked;data.request_id=requestId;try{const r=await fetch(api+(window.REGISTRATION_MODE==='payment'?'/checkout':'/register'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const res=await r.json();if(!r.ok)throw Error(res.error||'Could not open checkout.');if(res.registered){status.textContent=res.message+' Reference: '+res.registration_id;button.textContent='Registration received ✓';return;}const url=new URL(res.url);if(url.protocol!=='https:'||url.hostname!=='checkout.stripe.com')throw Error('Invalid checkout destination.');location.assign(url.href)}catch(err){status.textContent=err.message;button.disabled=false}});
function updatePlan(){const monthly=form.elements.plan.value==='monthly';document.querySelector('#summary-plan').textContent=monthly?'4 monthly payments':'Pay in full';document.querySelector('#summary-total').innerHTML=(monthly?'$2,000':'$1,800')+' <small>USD</small>';document.querySelector('#discount-row').hidden=monthly;document.querySelector('#summary-payment').textContent=monthly?'$500 after authorization, then $500 monthly for three more months.':'One payment when checkout is enabled.';}
form.querySelectorAll('[name="plan"]').forEach(input=>input.addEventListener('change',updatePlan));updatePlan();
function updateCourseDisplay(courses){function updateCourse(){const c=courses.find(c=>c.slug===form.elements.course.value);if(!c)return;document.querySelector('#selected-title').textContent=c.title;document.querySelector('#selected-desc').textContent=c.desc;document.querySelector('#summary-course').textContent=c.title;const art=document.querySelector('#course-art');art.src='images/'+c.slug+'.svg';art.alt=c.title+' illustration';art.hidden=false;}document.querySelector('#course').addEventListener('change',updateCourse);updateCourse();}

if(window.REGISTRATION_MODE!=='payment'){button.textContent='Submit registration ↗';document.querySelector('#checkout-note').textContent='No payment is taken when you submit. Your chosen plan is a preference for later payment.';const box=document.querySelector('.availability');box.querySelector('strong').textContent=window.REGISTRATION_API_URL?'Registration only · Payment later':'Registration setup in progress';box.querySelector('p').textContent=window.REGISTRATION_API_URL?'Submit your details without paying. Course availability and schedule will be confirmed separately.':'Details can be submitted once the registration backend is connected. Payments are not active.';const step=document.querySelectorAll('.next-steps li')[1];step.querySelector('strong').textContent='Submit your registration';step.querySelector('span').textContent='No charge is made. Payment is arranged later.';const consent=form.querySelector('.consent span');consent.innerHTML='I have read the <a href="registration-policy.html">registration and refund policy</a> and consent to using my details for registration and course communication. Choosing a payment plan now does not authorize a charge.';}
